// One translation per address.
function translateAll(pageSize, table, addrs) {
  return addrs.map(function (vaddr) {
    if (vaddr < 0) return 'INVALID';
    var page = Math.floor(vaddr / pageSize), off = vaddr % pageSize;
    if (page >= table.length) return 'INVALID';
    var f = table[page];
    return f === null || f === undefined ? 'PAGE FAULT' : f * pageSize + off;
  });
}
